protected void subAppend(LoggingEvent event) {
    // Check if the event is loggable
    if (!isAsSevereAsThreshold(event.getLevel())) {
        return;
    }

    // Determine the number of bytes to allocate
    int numBytes = event.getLoggerName().size();
    for (Object element : event.getParameters()) {
        numBytes += element.size();
    }

    // Allocate the bytes
    byte[] bytes = new byte[numBytes];
    int index = 0;

    // Write the logger name
    byte[] loggerNameBytes = event.getLoggerName().getBytes();
    for (int i = 0; i < loggerNameBytes.length; i++) {
        bytes[index++] = loggerNameBytes[i];
    }

    // Write the message
    byte[] messageBytes = event.getMessage().getBytes();
    for (int i = 0; i < messageBytes.length; i++) {
        bytes[index++] = messageBytes[i];
    }

    // Write the parameters
    for (Object parameter : event.getParameters()) {
        byte[] parameterBytes = parameter.toString().getBytes();
        for (int i = 0; i < parameterBytes.length; i++) {
            bytes[index++] = parameterBytes[i];
        }
    }

    // Write the timestamp
    byte[] timestampBytes = event.getTimestamp().toString().getBytes();
    for (int i = 0; i < timestampBytes.length; i++) {
        bytes[index++] = timestampBytes[i];
    }

    // Write the log level
    byte[] levelBytes = event.getLevel().toString().getBytes();
    for (int i = 0; i < levelBytes.length; i++) {
        bytes[index++] = levelBytes[i];
    }

    // Write the thread name
    byte[] threadNameBytes = event.getThreadName().getBytes();
    for (int i = 0; i < threadNameBytes.length; i++) {
        bytes[index++] = threadNameBytes[i];
    }

    // Write the exception
    if (event.getThrowableInformation() != null) {
        byte[] exceptionBytes = event.getThrowableInformation().toString().getBytes();
        for (int i = 0; i < exceptionBytes.length; i++) {
            bytes[index++] = exceptionBytes[i];
        }
    }

    // Flush the buffer
    buffer.flush();
}
