import java.util.*;

class GraphUtils {
    public static <V, E> GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
        List<E> edges = new ArrayList<E>(tour);
        List<V> vertices = new ArrayList<V>();

        for (E edge : edges) {
            vertices.add(edge.getSource());
            vertices.add(edge.getTarget());
        }

        if (vertices.size() % 2 == 1) {
            vertices.remove(vertices.size() - 1);
        }

        GraphPath<V, E> path = new GraphPath<V, E>(graph);
        for (int i = 0; i < vertices.size(); i += 2) {
            path.addEdge(graph.getEdge(vertices.get(i), vertices.get(i + 1)));
        }

        return path;
    }
}
